 public enum TileType
 {
 None,
 Block,
 }
 public class World
 {
 public static int width;
 public static int height;
 public static int scale = 10;
 public static TileType[,] tiles;
 public static void Generate(int width = 20, int height = 20)
 {
 World.width = width;
 World.height = height;

 TileType[,] tiles = new TileType[width, height];

 for (int x = 0; x < width; x++)
 {
 for (int y = 0; y < height; y++)
 {
 tiles[x, y] = TileType.Block;
 }
 }
 for (int x = 0; x < width; x++)
 {

 for (int y = 0; y < height; y++)
 {
 if ((x > 0 && x < width - 1) && (y > 0 && y < height - 1))
 {
 tiles[x, y] = TileType.None;
 }
 }
 }
 // Generate a random number of TileType blocks in the world (tiles)
 Random random = new Random();
 int blockCount = random.Next(10, 20);
 for (int i = 0; i < blockCount; i++)
 {
 int x = random.Next(0, width);
 int y = random.Next(0, height);
 tiles[x, y] = TileType.Block;
 }

 World.tiles = tiles;
 }
 public static void Draw()
 {
 Graphics.SetColor(Color.White);
 Graphics.Rectangle(DrawMode.Line, 0, 0, width \* scale, height \* scale);

 Graphics.SetColor(Color.Firebrick);
 for (int x = 0; x < width; x++)
 {
 for (int y = 0; y < height; y++)
 {
 if (tiles[x, y] == TileType.Block)
 {
 Graphics.Rectangle(DrawMode.Fill, x \* scale, y \* scale, scale, scale);
 }
 }
 }
 }
 }
 public class Player
 {
 public float x, y, w, h, speed, angle, directionX, directionY;
 public float sensitivity = 0.3f;
 public int fov = 60;
 public Player(float x, float y, float w = 30, float h = 50, float speed = 1, float angle = 0)
 {
 this.x = x;
 this.y = y;
 this.w = w;
 this.h = h;
 this.speed = speed;
 this.angle = angle;
