 public void Draw()
 {
 Graphics.SetColor(Color.AliceBlue);
 Graphics.SetPointSize(3);
 Graphics.Points(this.x \* World.scale, this.y \* World.scale);
 Graphics.SetColor(Color.White);
 Graphics.Print("X: " + this.x + " Y: " + this.y, 0, 0);
 Graphics.Print("Angle: " + this.angle, 0, 20);
 }
 public void Update(float dt)
 {
 Movement(dt);

 }

 private void Movement(float dt)
 {
 float directionX = 0;
 float directionY = 0;
 if (Keyboard.IsDown(KeyConstant.W))
 {
 directionY = -1;
 }
 if (Keyboard.IsDown(KeyConstant.S))
 {
 directionY = 1;
 }
 if (Keyboard.IsDown(KeyConstant.A))
 {
 directionX = -1;
 }
 if (Keyboard.IsDown(KeyConstant.D))
 {
 directionX = 1;
 }

 float rotatedDirectionX = (float)Math.Cos(this.angle) \* directionX - (float)Math.Sin(this.angle) \* directionY;
 float rotatedDirectionY = (float)Math.Sin(this.angle) \* directionX + (float)Math.Cos(this.angle) \* directionY;

 float directionLength = (float)Math.Sqrt(rotatedDirectionX \* rotatedDirectionX + rotatedDirectionY \* rotatedDirectionY);
 if (directionLength > 0)
 {
 rotatedDirectionX /= directionLength;
 rotatedDirectionY /= directionLength;
 }

 this.x += rotatedDirectionX \* this.speed \* dt;
 this.y += rotatedDirectionY \* this.speed \* dt;
 }
 public void Rotation(float dx)
 {
 this.angle += dx \* sensitivity \* Program.deltaTime;

 }
 }
 public class Ray
 {
 public static float distance;

 public static float Cast(float x, float y, float centerAngle, float fov)
 {
 float startX = x;
 float startY = y;
 string section;
 float quality = 0.1f;
 int screenWidth = 800;
 int screenHeight = 600;

 for (float angle = centerAngle - fov / 2; angle < centerAngle + fov / 2; angle += Quality(fov, quality, screenWidth))
 {
 float endX = (float)(startX + Math.Cos(angle) \* 1000);
 float endY = (float)(startY + Math.Sin(angle) \* 1000);

 section = FacingSection(angle);

 if (section == "NE")
 {
 for (float i = startX; i < endX; i += quality)
 {
 float j = (float)(startY + (i - startX) \* Math.Tan(angle));
 if (World.tiles[(int)i / World.scale, (int)j / World.scale] == TileType.Block)
 {
 distance = Distance(startX, startY, i, j);
 return distance;
 }
 }
 }
 else if (section == "NW")
 {
 for (float i = startX; i > endX; i -= quality)
 {
 float j = (float)(startY + (i - startX) \* Math.Tan(angle));
 if (World.tiles[(int)i / World.scale, (int)j / World.scale] == TileType.Block)
 {
 distance = Distance(startX, startY, i, j);
 return distance;
 }
 }
 }
 else if (section == "SW")
 {
 for (float i = startX; i > endX; i -= quality)
 {
 float j = (float)(startY + (i - startX) \* Math.Tan(angle));
 if (World.tiles[(int)i / World.scale, (int)j / World.scale] == TileType.Block)
 {
 distance = Distance(startX, startY, i, j);
 return distance;
 }
 }
 }
 else if (section == "SE")
 {
 for (float i = startX; i < endX; i += quality)
 {
 float j = (float)(startY + (i - startX) \* Math.Tan(angle));
 if (World.tiles[(int)i / World.scale, (int)j / World.scale] == TileType.Block)
 {
 distance = Distance(startX, startY, i, j);
 return distance;
 }
 }
 }
 }
 return 0;
 }
 public static string FacingSection(float angle)
 {
 string facing = "";
 if (angle >= 0 && angle < Math.PI / 2)
 {
 facing = "NE";
 }
 else if (angle >= Math.PI / 2 && angle < Math.PI)
 {
 facing = "NW";
 }
 else if (angle >= Math.PI && angle < 3 \* Math.PI / 2)
 {
 facing = "SW";
 }
 else if (angle >= 3 \* Math.PI / 2 && angle < 2 \* Math.PI)
 {
 facing = "SE";
 }
 return facing;
 }
 public static float Quality(float fov, float quality, float screenWidth)
 {

 // float angle = fov / screenWidth;
 // quality = angle / quality;
 // return quality;
 float angleBetweenRays = fov / screenWidth;
 float qualityAngle = (float)Math.Atan(quality / 2);
 float qualityAngleBetweenRays = qualityAngle / angleBetweenRays;
 return qualityAngleBetweenRays;
 }

 public static float Distance(float x1, float y1, float x2, float y2)
 {
 float distance = (float)Math.Sqrt((x2 - x1) \* (x2 - x1) + (y2 - y1) \* (y2 - y1));
 return distance;
 }

 public static void Draw(float x, float y, float distance, float angle, float fov)
 {

 float angleBetweenRays = fov / 800;
 float distanceToProjectionPlane = 800 / (2 \* (float)Math.Tan(fov / 2));
 float distanceToWall = distance;
 float distanceToProjectionPoint = distanceToWall \* (float)Math.Cos(angleBetweenRays);
 distanceToProjectionPlane = distanceToProjectionPoint \* distanceToProjectionPlane / distanceToWall;
 float height = 600 / distanceToProjectionPlane;
 float width = 1;
 float color = 255 / distanceToWall;
 Graphics.SetColor(Color.FromRGBA(color, color, color, 255));
 Graphics.Rectangle(DrawMode.Fill, x, y - height / 2, width, height);


 }
 public static void Update(float x, float y, float angle, float fov)
 {
 Cast(x, y, angle, fov);


 }
 }
}

