void ss_encrypt_file(FILE *infile, FILE *outfile, mpz_t n) {
    size_t k = (mpz_sizeinbase(n, 2) - 1) / 16;
    uint8_t *block = malloc(k);
    block[0] = 0xFF;
    while (1) {
        size_t j = fread(&block[1], 1, k - 1, infile);
        if (j == 0) {
            break;
        }
        mpz_t m;
        mpz_init(m);
