Write me a NodeJS authentication flow for this API using ExpressJS
To create a Node.js authentication flow for the Genius API using Express.js, you can follow these steps:

1. Install required dependencies:
```arduino
npm init
npm install express request request-promise dotenv express-session
```
1. Create a `.env` file in your project's root directory to store your API credentials:
```makefile
GENIUS_CLIENT_ID=your_client_id
GENIUS_CLIENT_SECRET=your_client_secret
GENIUS_REDIRECT_URI=http://localhost:3000/callback
SESSION_SECRET=your_session_secret
```
Replace `your_client_id`, `your_client_secret`, and `your_session_secret` with the appropriate values.

1. Create a `server.js` file in your project's root directory and add the following code:
```javascript
require('dotenv').config();
const express = require('express');
const request = require('request-promise');
const session = require('express-session');

const app = express();

app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false
}));

app.get('/', (req, res) => {
  res.send('<a href="/auth">Login with Genius</a>');
});

app.get('/auth', (req, res) => {
  const authUrl = `https://api.genius.com/oauth/authorize?client_id=${process.env.GENIUS_CLIENT_ID}&redirect_uri=${process.env.GENIUS_REDIRECT_URI}&scope=me&response_type=code`;
  res.redirect(authUrl);
});

app.get('/callback', async (req, res) => {
  try {
    const code = req.query.code;
    const token = await requestAccessToken(code);
    req.session.access_token = token.access_token;
    res.redirect('/me');
  } catch (error) {
    console.error('Error during token request:', error);
    res.redirect('/');
  }
});

app.get('/me', async (req, res) => {
  try {
    const userProfile = await requestGeniusUserProfile(req.session.access_token);
    res.json(userProfile);
  } catch (error) {
    console.error('Error during user profile request:', error);
    res.redirect('/');
  }
});

async function requestAccessToken(code) {
  const options = {
    method: 'POST',
    uri: 'https://api.genius.com/oauth/token',
    form: {
      code: code,
      client_id: process.env.GENIUS_CLIENT_ID,
      client_secret: process.env.GENIUS_CLIENT_SECRET,
      redirect_uri: process.env.GENIUS_REDIRECT_URI,
      response_type: 'code',
      grant_type: 'authorization_code'
    },
    json: true
  };

  return await request(options);
}

async function requestGeniusUserProfile(access_token) {
  const options = {
    method: 'GET',
    uri: 'https://api.genius.com/account',
    headers: {
      'Authorization': `Bearer ${access_token}`
    },
    json: true
  };

  return await request(options);
}

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```
Now you can run your server by executing `node server.js`. Visit <http://localhost:3000> to start the authentication flow. After successful authentication, you'll be redirected to the `/me` route, which will display the user's account information in JSON format.
Make 'express-session' use Firebase Store as a session storage
To use Firebase as a session store with `express-session`, you'll first need to install the `express-session` and `firebase-admin` packages. You can use `npm` or `yarn` to do this:
```bash
npm install express-session firebase-admin
```
Next, you'll need to set up your Firebase project and obtain the necessary credentials. To do this, follow the instructions in the [official Firebase documentation](https://firebase.google.com/docs/admin/setup).

Once you have your Firebase project set up and your credentials, you can create a custom session store for `express-session` that uses Firebase. Here's an example of how you can set up an Express server that uses Firebase for session storage:
```javascript
const express = require('express');
const session = require('express-session');
const firebaseAdmin = require('firebase-admin');
const { Firestore } = require('@google-cloud/firestore');

const app = express();

// Initialize Firebase
const serviceAccount = require('./path/to/your/firebase-service-account-key.json');

firebaseAdmin.initializeApp({
  credential: firebaseAdmin.credential.cert(serviceAccount),
});

const firestore = new Firestore();

class FirestoreSessionStore {
  constructor() {
    this.collection = firestore.collection('sessions');
  }

  async get(sid) {
    const sessionDoc = await this.collection.doc(sid).get();

    if (!sessionDoc.exists) {
      return null;
    }

    const sessionData = sessionDoc.data();
    return JSON.parse(sessionData.json);
  }

  async set(sid, session) {
    await this.collection.doc(sid).set({
      json: JSON.stringify(session),
    });

    return session;
  }

  async destroy(sid) {
    await this.collection.doc(sid).delete();
  }
}

app.use(
  session({
    secret: 'your-session-secret',
    store: new FirestoreSessionStore(),
    resave: false,
    saveUninitialized: false,
    cookie: { secure: false, maxAge: 24 * 60 * 60 * 1000 }, // 1 day
  })
);

app.get('/', (req, res) => {
  if (req.session.views) {
    req.session.views++;
    res.send(`<p>Session ID: ${req.sessionID}. Views: ${req.session.views}</p>`);
  } else {
    req.session.views = 1;
    res.send(`<p>Session ID: ${req.sessionID}. Welcome! This is your first visit.</p>`);
  }
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
```
This code sets up an Express server that stores session data in a Firestore collection called `sessions`. Make sure to replace `'./path/to/your/firebase-service-account-key.json'` with the actual path to your service account JSON file.

Keep in mind that this example is a basic implementation of a session store. In a production environment, you may want to handle errors, implement additional methods, and add more sophisticated features like session expiration.
