    int nbPas = 4000 / nbPoses;
    long pause = tpsPose / 4.0 * 1000;

    for (int i = 1; i <= nbPoses; i++) {
      // Afficher l'interface utilisateur sur l'écran OLED
      display.clearDisplay();
      display.setTextSize(2);
      display.setCursor(0, 0);
      display.print("Photo : ");
      display.setCursor(0, 35);
      display.print(i);
      display.print("/");
      display.print(nbPoses);
      display.setCursor(0, 45);
      display.setTextSize(1);
      display.print("Temps restant : ");
      display.print(nbPoses * tpsPose / 4.0 + nbPoses * 2);
      display.print("s");
      display.display();
