function detectClickFraud() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getDataRange();
  var data = dataRange.getValues();
  var numRows = dataRange.getNumRows();
  var numCols = dataRange.getNumColumns();

  // Find the first blank column
  var headerRow = data[0];
  var firstBlankCol = headerRow.findIndex(function(col) {
    return col === '';
  });

  // If there are no blank columns, insert a new column to the right of the last column
  if (firstBlankCol == -1) {
    firstBlankCol = numCols + 1;
    sheet.insertColumnAfter(numCols);
  }

  // Calculate the likelihood of click fraud in each row
  for (var i = 1; i < numRows; i++) {
    var row = data[i];
    var clicks = row[0];
    var impressions = row[1];
    var ctr = clicks / impressions;
    var conversionRate = row[2] / clicks;
    var costPerConversion = row[3] / row[2];
    var likelihood = ctr + conversionRate + costPerConversion;

    // Write the likelihood percentage in the first blank column next to the row
    sheet.getRange(i+1, firstBlankCol).setValue(likelihood * 100 + '%');
  }
}
```
