```javascript
const express = require('express');
const session = require('express-session');
const firebaseAdmin = require('firebase-admin');
const { Firestore } = require('@google-cloud/firestore');
const { EventEmitter } = require('events');

const app = express();

// Initialize Firebase
const serviceAccount = require('./path/to/your/firebase-service-account-key.json');

firebaseAdmin.initializeApp({
  credential: firebaseAdmin.credential.cert(serviceAccount),
});

const firestore = new Firestore();

class FirestoreSessionStore extends EventEmitter {
  constructor() {
    super();
    this.collection = firestore.collection('sessions');
  }

  async get(sid, callback) {
    try {
      const sessionDoc = await this.collection.doc(sid).get();
      const sessionData = sessionDoc.exists ? JSON.parse(sessionDoc.data().json) : null;
      callback(null, sessionData);
    } catch (error) {
      callback(error);
    }
  }

  async set(sid, session, callback) {
    try {
      await this.collection.doc(sid).set({
        json: JSON.stringify(session),
      });
      callback(null);
    } catch (error) {
      callback(error);
    }
  }

  async destroy(sid, callback) {
    try {
      await this.collection.doc(sid).delete();
      callback(null);
    } catch (error) {
      callback(error);
    }
  }

  async all(callback) {
    try {
      const snapshot = await this.collection.get();
      const sessions = snapshot.docs.map(doc => JSON.parse(doc.data().json));
      callback(null, sessions);
    } catch (error) {
      callback(error);
    }
  }

  async length(callback) {
    try {
      const snapshot = await this.collection.get();
      callback(null, snapshot.size);
    } catch (error) {
      callback(error);
    }
  }

  async clear(callback) {
    try {
      const snapshot = await this.collection.get();
      const deletePromises = snapshot.docs.map(doc => doc.ref.delete());
      await Promise.all(deletePromises);
      callback(null);
    } catch (error) {
      callback(error);
    }
  }
}

app.use(
  session({
    secret: 'your-session-secret',
    store: new FirestoreSessionStore(),
    resave: false,
    saveUninitialized: false,
    cookie: { secure: false, maxAge: 24 * 60 * 60 * 1000 }, // 1 day
  })
);

app.get('/', (req, res) => {
  if (req.session.views) {
    req.session.views++;
    res.send(`<p>Session ID: ${req.sessionID}. Views: ${req.session.views}</p>`);
  } else {
    req.session.views = 1;
    res.send(`<p>Session ID: ${req.sessionID}. Welcome! This is your first visit.</p>`);
  }
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
```
In this updated version, the `FirestoreSessionStore` extends the `EventEmitter` class, and the `get`, `set`, `destroy`, `all`, `length`, and `clear` methods have been updated to accept and use callback functions, which is required by the `express-session` store API.

This should resolve the error, and you should be able to use the custom Firebase session store with your Express server without issues.
