Pour remplacer le `delay(pause)` par une fonction non bloquante et permettre à l'utilisateur de sortir de la fonction `pdv()` en appuyant sur le bouton OK, vous pouvez utiliser la fonction `millis()` pour suivre le temps écoulé. Voici la fonction `pdv()` modifiée:
```cpp
void pdv() {
  digitalWrite(ENABLE_PIN, 0);
  Moteur.setCurrentPosition(0);
  Moteur.moveTo(0);
  bool stopAll = false;
  bool stopOne = false;
  display.clearDisplay();
  display.setCursor(0, 0);
  display.setTextSize(1);
  display.print("Lancement de la PDV ");
  display.display();
  delay(1000);
  while (!stopAll) {
    int nbPas = 4000 / nbPoses;
    long pause = tpsPose / 4.0 * 1000;

    for (int i = 1; i <= nbPoses; i++) {
      // Afficher l'interface utilisateur sur l'écran OLED
      display.clearDisplay();
      display.setTextSize(2);
      display.setCursor(0, 0);
      display.print("Photo : ");
      display.setCursor(0, 35);
      display.print(i);
      display.print("/");
      display.print(nbPoses);
      display.setCursor(0, 45);
      display.setTextSize(1);
      display.print("Temps restant : ");
      display.print(nbPoses * tpsPose / 4.0 + nbPoses * 2);
      display.print("s");
      display.display();
      Moteur.moveTo(nbPas * i);
      while (!stopOne) {
        if (Moteur.distanceToGo() == 0) stopOne = true;
        if (!digitalRead(BTN_OK)) {
          Moteur.stop();
          stopOne = true;
          stopAll = true;
          i = nbPoses;
          break;
        }
        // Mettre à jour la position du moteur
        Moteur.run();
      }
      stopOne = false;
      // Indiquer que l'arrêt est terminé avec une LED verte
      digitalWrite(LED_G, HIGH);
      beepR();

      // Remplacer le delay(pause) par une fonction non bloquante
      unsigned long startTime = millis();
      while (millis() - startTime < pause) {
        if (!digitalRead(BTN_OK)) {
          stopAll = true;
          break;
        }
      }

      digitalWrite(LED_G, LOW);
      if (stopAll) break;  // Sortir de la boucle for si l'utilisateur appuie sur le bouton OK
    }
  }

  // Afficher un message pour indiquer que la PDV est terminée
  display.clearDisplay();
  display.setCursor(0, 0);
  display.print("Fin de la PDV");
  display.display();
  digitalWrite(ENABLE_PIN, 1);
  delay(1000);
}
```
La boucle `while (millis() - startTime < pause)` remplace le `delay(pause)` et vérifie si le bouton OK est enfoncé pendant la pause. Si c'est le cas, la variable `stopAll` est définie sur `true` et la boucle `for` est interrompue.
